function rank(n, key){ if(!n) return 0; if(key <= n.key) return rank(n.left, key); return (n.left?.size||0) + n.cnt + rank(n.right, key); }
function kth(n, k){ if(!n) return null; const ls = n.left?.size||0; if(k <= ls) return kth(n.left, k); if(k <= ls + n.cnt) return n.key; return kth(n.right, k - ls - n.cnt); }
